import{_ as s,a0 as p,w as i,s as m,ao as o,I as r,x as t,a1 as a,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"elementary OS 系统走到头了吗？ | LCTT x X-CMD","titleTemplate":false,"description":"elementary OS 系统走到头了吗？ | LCTT (202204) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"elementary OS 系统走到头了吗？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"elementary OS 系统走到头了吗？ | LCTT (202204) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202204/20220403 Is this the End of the road for elementary OS","title":"elementary OS 系统走到头了吗？","tag":"202204","desc":""},"relativePath":"202204/20220403 Is this the End of the road for elementary OS.md","filePath":"[post].md"}'),d={name:"202204/20220403 Is this the End of the road for elementary OS.md"};function u(y,e,f,S,O,T){const n=p("Link");return i(),m("div",null,[e[20]||(e[20]=o('<h1 id="elementary-os-系统走到头了吗" tabindex="-1">elementary OS 系统走到头了吗？ <a class="header-anchor" href="#elementary-os-系统走到头了吗" aria-label="Permalink to “elementary OS 系统走到头了吗？”">​</a></h1><blockquote><p>Cassidy James 是 elementary OS 系统的创始人，根据他最近的声明得知他已经辞职。下面是我们对这一话题的看法，以及可能的未来。</p></blockquote><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/08/elementary-OS-6-ODIN-Desktop-1024x576.jpeg" alt="elementary OS 6 ODIN Desktop"></p><p>早在十年前，当 elementary OS 首次发布时，它率先带领 Linux 桌面领域迈出了新的一步。Cassidy 有一个愿景，从那时只有开发者和贡献者在使用的 Linux 桌面，到全世界用户都能够使用它。它的 Pantheon 桌面是最好的桌面之一，从一开始就是为美学和生产力而设计的。</p><p>多年来，elementary OS 已经成长起来了。它的用户群和受欢迎程度一直在增加，因为它的稳定性、基于 Ubuntu 长期支持版，对于那些希望在 Linux 中拥有类似 macOS 的用户界面的人来说，是一个完美的桌面。它的基于 Flatpak 的应用商店也是在 Linux 生态系统中最好的应用商店之一，具有一套精心打造的应用程序。</p><p>如果你用免费软件经营公司，除非你有一个在背后支撑的企业和其它盈利模式，否则这些优势和良好的用户反馈，是无法变成盈利的。</p><h3 id="为什么会出现这种情况-这是-elementary-os-系统的终点吗" tabindex="-1">为什么会出现这种情况，这是 elementary OS 系统的终点吗？ <a class="header-anchor" href="#为什么会出现这种情况-这是-elementary-os-系统的终点吗" aria-label="Permalink to “为什么会出现这种情况，这是 elementary OS 系统的终点吗？”">​</a></h3><p>elementary OS 有一个 “付费下载” 的收入模式，这是自愿的。但是疫情已经两年了，这方面的销售收入也在下降，该公司的领导层为了维持公司运转，已经削减了全职员工的工资和医疗福利。</p><blockquote><p>“自从我全职投入 elementary 公司以来，每一个版本的销售业绩都要比上一个表现要好，直到 OS 6 和 6.1 的业绩表现远远低于预期，部分原因是持续的全球疫情，人们看起来在能免费下载操作系统的时候，不再想支付可选的金额来下载它。很明显，我们需要重新确定我们公司财务的优先次序，同时坚定我们的开源、以隐私为中心和道德的筹资信念。”Cassidy 在他的告别信中说道。</p></blockquote>',9)),r("p",null,[e[1]||(e[1]=t("全球经济在疫情的打击下，所有人和事都无法幸免。",-1)),a(n,{href:"https://www.debugpoint.com/2021/08/elementary-os-6-odin-review/"},{default:l(()=>[...e[0]||(e[0]=[t("elementary OS 6 Odin",-1)])]),_:1}),e[2]||(e[2]=t(" 的发布并不顺利。有一些错误、英伟达显卡的问题和其他问题，全球疫情和贡献的减少也影响了软件的质量。这最终影响到了自愿付费下载的收入。",-1))]),e[21]||(e[21]=o('<p>自愿付费下载模式、GitHub 的赞助，用来维持企业运转和大型项目是远远不够的。如果你看看其他的主流开源项目，如 Fedora Linux、GNOME、KDE Plasma，它们都有来自 Red Hat、IBM、Google 等大企业的大量赞助。而这是有原因的，这些大公司都从这些开源项目中获得商业利益。但是对于 elementary OS 来说，情况就有点不同了。</p><blockquote><p>Cassidy 又写道，“结果，Dani 要求我辞职，并完全离开 elementary。在我寻找另一个职位时，这并不是我的本意，但是 Dani 一直坚持（要我离开）。最后，我决定，最好的行动方案确实是我继续前行；我放弃了我对 elementary 十多年的激情，接受了 Dani 的提议，让她成为 elementary 公司唯一的、100% 的所有者。我已经签署了我的辞呈。从今天起，她现在拥有公司的所有股份和责任。我祝愿她在延续公司的遗产方面取得最好的成绩。”</p></blockquote><h3 id="展望未来" tabindex="-1">展望未来 <a class="header-anchor" href="#展望未来" aria-label="Permalink to “展望未来”">​</a></h3><p>确实，我能在告别信中感受到 Cassidy 的感情。放弃你多年来建立的项目和激情是不容易的。那里有你在为社区获得更大利益的愿景而投入的无数个日日夜夜。你的感情与之相连。放弃并不容易。</p><p>没有人能够预测未来。所以，我们不知道在未来的日子里 elementary OS 系统作为一个项目会发生什么。当情况发生了，开源公司最终会成为一个有更多受众和贡献者的社区项目。我觉得新的领导人需要看看 elementary OS 在 Linux 发行版或桌面领域方面的未来路线图。</p><p>因为带有 GTK4/libadwaita 的 GNOME 42+ 看起来很有前途，elementary OS 可能会因为 GNOME 而失去用户群。在这种情景下，唯一的卖点只有 Pantheon 桌面，这就需要更多的打磨和市场化能力，同时新的领导层也需要寻找更好的收入模式。</p><p>我们希望，作为一个社区，elementary OS 能够继续推出新版本，如果必要的话，让它成为没有 GitHub 赞助墙的社区项目。而我认为寻找企业基金和捐赠也可以成为维持项目运行的长期选择之一。</p><p>任何开源项目都不应该停止。我希望新的领导层能够找到更好的收入模式来维持这个项目。只要思想不滑坡，方法总比困难多。</p><p>所以，关于这整个情况你有什么看法？在下方评论让我知道。</p><p>谢谢。</p>',10)),r("p",null,[r("em",null,[e[4]||(e[4]=t("部分引用自 ",-1)),a(n,{href:"https://cassidyjames.com/blog/farewell-elementary/"},{default:l(()=>[...e[3]||(e[3]=[t("Cassidy 的博客",-1)])]),_:1})])]),e[22]||(e[22]=r("hr",null,null,-1)),r("p",null,[e[6]||(e[6]=t("via: ",-1)),a(n,{href:"https://www.debugpoint.com/2022/04/end-of-elementary-os/"},{default:l(()=>[...e[5]||(e[5]=[t("https://www.debugpoint.com/2022/04/end-of-elementary-os/",-1)])]),_:1})]),r("p",null,[e[11]||(e[11]=t("作者：",-1)),a(n,{href:"https://www.debugpoint.com/author/admin1/"},{default:l(()=>[...e[7]||(e[7]=[t("Arindam",-1)])]),_:1}),e[12]||(e[12]=t(" 选题：",-1)),a(n,{href:"https://github.com/lujun9972"},{default:l(()=>[...e[8]||(e[8]=[t("lujun9972",-1)])]),_:1}),e[13]||(e[13]=t(" 译者：",-1)),a(n,{href:"https://github.com/hwlife"},{default:l(()=>[...e[9]||(e[9]=[t("hwlife",-1)])]),_:1}),e[14]||(e[14]=t(" 校对：",-1)),a(n,{href:"https://github.com/wxy"},{default:l(()=>[...e[10]||(e[10]=[t("wxy",-1)])]),_:1})]),r("p",null,[e[17]||(e[17]=t("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[15]||(e[15]=[t("LCTT",-1)])]),_:1}),e[18]||(e[18]=t(" 原创编译，",-1)),a(n,{href:"https://linux.cn/"},{default:l(()=>[...e[16]||(e[16]=[t("Linux中国",-1)])]),_:1}),e[19]||(e[19]=t(" 荣誉推出",-1))])])}const x=s(d,[["render",u]]);export{C as __pageData,x as default};
